/**
 * streamId derivation (§7.5).
 *
 * Implements deterministic streamId generation from file metadata and content samples.
 * Critical for cross-session resume (D22): re-selecting the same file MUST reproduce
 * the same streamId.
 *
 * **Derivation (sender):**
 * ```
 * streamId = CRC32( originalSize ‖ first 64 KB ‖ middle 64 KB ‖ last 64 KB ‖ lastModified )
 * ```
 *
 * **Critical:** `originalSize` is the **uncompressed** file size (the beacon's `originalSize`
 * field), NOT the compressed payload size (`payloadLen`). This is required because:
 *
 * - **Resume (D22):** `streamId` identifies the FILE the user selected, not the compressed
 *   version. Using `originalSize` ensures the same file always produces the same `streamId`
 *   regardless of compression settings.
 * - **Security separation:** E3a's block arithmetic uses `payloadLen` (compressed size) from
 *   the beacon to compute the last block's short length. T1's quota check, T3's decompression-
 *   bomb cap, and D23's ETA all use `originalSize` from the beacon. `streamId` participates
 *   in the original-size domain because it identifies the user's chosen file.
 *
 * Three sampled windows plus size and mtime. Costs ~200 KB of reads regardless of file size,
 * so it is instant even for 4 TB.
 *
 * **What this buys and what it does not:**
 *
 * - ✅ Same file re-selected → same `streamId` → resume works.
 * - ✅ Different files → different `streamId` with overwhelming probability.
 * - ⚠️ A file edited **only in the middle**, keeping size and mtime, collides. Mitigated by
 *   including `lastModified`, and by per-block hashes catching the mismatch at block level.
 * - ⚠️ This is **not** a content-integrity hash. The whole-file hash (§7.2) **is** a
 *   content-integrity hash and is mandatory per concept.md constraint 4. `streamId` is an
 *   *identifier*.
 *
 * Deliberately **not** `crc32(payload)` — the research's original design — because the
 * block layer made a full-payload pass unaffordable.
 *
 * Reference: plan.md §7.5, D22, D7
 */

import {crc32} from '../frame/crc.js';

/**
 * Sample size for each window (first, middle, last).
 *
 * 64 KB is chosen to provide strong identification at minimal read cost.
 * Three samples = 192 KB of data regardless of file size.
 */
export const STREAM_ID_SAMPLE_SIZE = 64 * 1024; // 64 KB

/**
 * Maximum total read size for streamId computation.
 *
 * Used for progress tracking and bounds checking.
 */
export const STREAM_ID_MAX_READ = STREAM_ID_SAMPLE_SIZE * 3 + 24; // 3 samples + size + mtime

/**
 * Compute streamId from a File object.
 *
 * This is the primary entry point for sender-side streamId generation.
 * It reads three samples from the file, combines them with metadata,
 * and computes the CRC-32 to produce a deterministic identifier.
 *
 * **Performance:** For large files, this is much faster than reading the entire file.
 * For a 4 GB file, this reads ~200 KB instead of 4 GB (~20,000× faster).
 *
 * **Browser compatibility:** Uses File.slice() which is available in all modern browsers.
 * The slice operation is zero-copy in most implementations.
 *
 * @param file - File object to identify
 * @returns Promise resolving to 32-bit streamId
 * @throws {Error} If file reading fails
 *
 * @example
 * ```ts
 * const file = fileInput.files[0];
 * const streamId = await computeStreamId(file);
 * beacon.streamId = streamId;
 * ```
 */
export async function computeStreamId(file: File): Promise<number> {
  const originalSize = file.size;
  const lastModified = file.lastModified;

  // Handle zero-byte files (E1)
  if (originalSize === 0) {
    throw new Error('Cannot compute streamId for zero-byte file (E1)');
  }

  // Handle files smaller than one sample
  if (originalSize <= STREAM_ID_SAMPLE_SIZE * 3) {
    // Small file: read the whole thing and use it as all three samples
    const sample = await readFileSlice(file, 0, originalSize);
    return computeStreamIdFromSamples(originalSize, lastModified, sample, sample, sample);
  }

  // Large file: read three samples
  const firstSample = await readFileSlice(file, 0, STREAM_ID_SAMPLE_SIZE);

  const middleOffset = Math.floor((originalSize - STREAM_ID_SAMPLE_SIZE) / 2);
  const middleSample = await readFileSlice(file, middleOffset, STREAM_ID_SAMPLE_SIZE);

  const lastOffset = originalSize - STREAM_ID_SAMPLE_SIZE;
  const lastSample = await readFileSlice(file, lastOffset, STREAM_ID_SAMPLE_SIZE);

  return computeStreamIdFromSamples(
    originalSize,
    lastModified,
    firstSample,
    middleSample,
    lastSample
  );
}

/**
 * Read a slice from a File object.
 *
 * Helper function to read a range of bytes from a file using File.slice().
 * Uses FileReader for browser compatibility (File.arrayBuffer() is newer).
 *
 * @param file - File to read from
 * @param start - Starting byte offset
 * @param length - Number of bytes to read
 * @returns Promise resolving to Uint8Array of the slice
 * @throws {Error} If read fails
 */
async function readFileSlice(file: File, start: number, length: number): Promise<Uint8Array> {
  const slice = file.slice(start, start + length);

  return new Promise<Uint8Array>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (reader.result === null) {
        reject(new Error('FileReader returned null'));
        return;
      }
      // Get raw bytes from ArrayBuffer
      resolve(new Uint8Array(reader.result as ArrayBuffer));
    };
    reader.onerror = () => reject(new Error(`FileReader error: ${reader.error}`));
    reader.readAsArrayBuffer(slice);
  });
}

/**
 * Compute streamId from pre-read samples.
 *
 * This is the core derivation function. It combines the metadata and samples
 * in the exact order specified by the plan and computes the CRC-32.
 *
 * **Order is normative:** The exact concatenation order is part of the wire format.
 * Changing this order would change streamId values and break compatibility.
 *
 * **Format:**
 * ```
 * [originalSize: 8 bytes big-endian]
 * [firstSample: STREAM_ID_SAMPLE_SIZE bytes]
 * [middleSample: STREAM_ID_SAMPLE_SIZE bytes]
 * [lastSample: STREAM_ID_SAMPLE_SIZE bytes]
 * [lastModified: 8 bytes big-endian]
 * ```
 *
 * @param originalSize - Uncompressed file size in bytes
 * @param lastModified - File modification timestamp (ms since epoch)
 * @param firstSample - First 64 KB of file
 * @param middleSample - Middle 64 KB of file
 * @param lastSample - Last 64 KB of file
 * @returns 32-bit streamId
 */
export function computeStreamIdFromSamples(
  originalSize: number,
  lastModified: number,
  firstSample: Uint8Array,
  middleSample: Uint8Array,
  lastSample: Uint8Array
): number {
  // Calculate total size: 8 + 8 + 3 samples
  const totalSize = 8 + 8 + firstSample.length + middleSample.length + lastSample.length;

  // Create combined buffer
  const combined = new Uint8Array(totalSize);
  let offset = 0;

  // Write originalSize as 8-byte big-endian
  writeU64BE(combined, offset, originalSize);
  offset += 8;

  // Write samples
  combined.set(firstSample, offset);
  offset += firstSample.length;

  combined.set(middleSample, offset);
  offset += middleSample.length;

  combined.set(lastSample, offset);
  offset += lastSample.length;

  // Write lastModified as 8-byte big-endian
  writeU64BE(combined, offset, lastModified);
  offset += 8;

  // Compute CRC-32
  return crc32(combined);
}

/**
 * Write a 64-bit unsigned integer as big-endian bytes.
 *
 * @param buffer - Buffer to write to
 * @param offset - Starting offset
 * @param value - Value to write (treated as unsigned)
 */
function writeU64BE(buffer: Uint8Array, offset: number, value: number): void {
  // Use >>> 0 to force unsigned interpretation
  const v = value >>> 0;
  buffer[offset] = (v >>> 56) & 0xff;
  buffer[offset + 1] = (v >>> 48) & 0xff;
  buffer[offset + 2] = (v >>> 40) & 0xff;
  buffer[offset + 3] = (v >>> 32) & 0xff;
  buffer[offset + 4] = (v >>> 24) & 0xff;
  buffer[offset + 5] = (v >>> 16) & 0xff;
  buffer[offset + 6] = (v >>> 8) & 0xff;
  buffer[offset + 7] = v & 0xff;
}

/**
 * Compute streamId from raw file bytes (for testing).
 *
 * This is a convenience function for tests that already have the file bytes.
 * It handles small files automatically.
 *
 * @param fileBytes - Complete file contents
 * @param lastModified - File modification timestamp
 * @returns 32-bit streamId
 */
export function computeStreamIdFromBytes(fileBytes: Uint8Array, lastModified: number): number {
  const originalSize = fileBytes.length;

  if (originalSize === 0) {
    throw new Error('Cannot compute streamId for zero-byte file (E1)');
  }

  if (originalSize <= STREAM_ID_SAMPLE_SIZE * 3) {
    // Small file: use whole file as all three samples
    return computeStreamIdFromSamples(
      originalSize,
      lastModified,
      fileBytes,
      fileBytes,
      fileBytes
    );
  }

  // Large file: extract three samples
  const firstSample = fileBytes.slice(0, STREAM_ID_SAMPLE_SIZE);

  const middleOffset = Math.floor((originalSize - STREAM_ID_SAMPLE_SIZE) / 2);
  const middleSample = fileBytes.slice(middleOffset, middleOffset + STREAM_ID_SAMPLE_SIZE);

  const lastOffset = originalSize - STREAM_ID_SAMPLE_SIZE;
  const lastSample = fileBytes.slice(lastOffset);

  return computeStreamIdFromSamples(
    originalSize,
    lastModified,
    firstSample,
    middleSample,
    lastSample
  );
}

/**
 * Validate that a streamId matches expected value.
 *
 * Used by the receiver to lock onto the correct stream when multiple senders
 * are visible (A9). Also used for E18 resume mismatch detection.
 *
 * @param file - File to check
 * @param expectedStreamId - Expected streamId value
 * @returns Promise resolving to true if streamId matches
 * @throws {Error} If computation fails
 */
export async function validateStreamId(file: File, expectedStreamId: number): Promise<boolean> {
  const actualStreamId = await computeStreamId(file);
  return actualStreamId === expectedStreamId;
}

/**
 * Block bitmap operations for resume (D22).
 *
 * The receiver persists the completed-block bitmap; incomplete blocks restart rather
 * than persisting partial GE state. At 2.7 KB per 4 GB for the bitmaps this is
 * nearly free.
 *
 * **Bitmap structure:**
 * - One bit per block (1 = complete, 0 = incomplete)
 * - Size: ceil(blockCount / 8) bytes
 * - For 4 GB file (21,845 blocks): ~2.7 KB
 *
 * **Two bitmaps (session/types.ts BaseRecvState):**
 * - `complete`: blocks that have reached rank K (decoded)
 * - `writtenBlocks`: blocks that have been written to OPFS
 *
 * The separation is required for I9: blocks reaching rank K before their hash
 * arrives MAY be written to OPFS but MUST NOT be surfaced to the user until verified.
 *
 * Reference: plan.md §8.3, D22, I9
 */

/**
 * Calculate bitmap size in bytes for a given block count.
 *
 * @param blockCount - Number of blocks
 * @returns Number of bytes needed for the bitmap
 */
export function getBitmapSize(blockCount: number): number {
  return Math.ceil(blockCount / 8);
}

/**
 * Create a new empty bitmap (all zeros).
 *
 * @param blockCount - Number of blocks
 * @returns New bitmap initialized to all zeros
 */
export function createEmptyBitmap(blockCount: number): Uint8Array {
  const size = getBitmapSize(blockCount);
  return new Uint8Array(size);
}

/**
 * Create a new bitmap with specific blocks set.
 *
 * @param blockCount - Number of blocks
 * @param setBlocks - Array of block indices to set
 * @returns New bitmap with specified blocks set
 */
export function createBitmapWithBlocks(blockCount: number, setBlocks: number[]): Uint8Array {
  const bitmap = createEmptyBitmap(blockCount);
  for (const blockIndex of setBlocks) {
    if (blockIndex >= 0 && blockIndex < blockCount) {
      setBitmapBit(bitmap, blockIndex);
    }
  }
  return bitmap;
}

/**
 * Check if a specific block bit is set.
 *
 * @param bitmap - Block bitmap
 * @param blockIndex - Block index to check
 * @returns true if the block bit is set (complete), false otherwise
 */
export function isBitmapBitSet(bitmap: Uint8Array, blockIndex: number): boolean {
  const byteIndex = Math.floor(blockIndex / 8);
  const bitIndex = blockIndex % 8;
  return (bitmap[byteIndex]! & (1 << bitIndex)) !== 0;
}

/**
 * Set a specific block bit in the bitmap.
 *
 * @param bitmap - Block bitmap
 * @param blockIndex - Block index to set
 */
export function setBitmapBit(bitmap: Uint8Array, blockIndex: number): void {
  const byteIndex = Math.floor(blockIndex / 8);
  const bitIndex = blockIndex % 8;
  bitmap[byteIndex]! |= (1 << bitIndex);
}

/**
 * Clear a specific block bit in the bitmap.
 *
 * Used for E12 block hash failure when a block needs to be re-collected.
 *
 * @param bitmap - Block bitmap
 * @param blockIndex - Block index to clear
 */
export function clearBitmapBit(bitmap: Uint8Array, blockIndex: number): void {
  const byteIndex = Math.floor(blockIndex / 8);
  const bitIndex = blockIndex % 8;
  bitmap[byteIndex]! &= ~(1 << bitIndex);
}

/**
 * Count the number of set bits in a bitmap.
 *
 * Uses efficient population count (popcount) algorithm.
 *
 * @param bitmap - Block bitmap
 * @returns Number of set bits (complete blocks)
 */
export function countSetBits(bitmap: Uint8Array): number {
  let count = 0;
  for (const byte of bitmap) {
    count += popcount(byte);
  }
  return count;
}

/**
 * Population count (number of set bits) for a byte.
 *
 * Uses the classic popcount algorithm with parallel bit counting.
 *
 * @param x - Byte value
 * @returns Number of set bits
 */
function popcount(x: number): number {
  x = x - ((x >> 1) & 0x55);
  x = (x & 0x33) + ((x >> 2) & 0x33);
  return (x + (x >> 4)) & 0x0f;
}

/**
 * Get all block indices with unset bits (missing blocks).
 *
 * Returns the complement of the set bits - useful for resume and repair codes.
 *
 * @param bitmap - Block bitmap
 * @returns Array of block indices that are NOT set (incomplete)
 */
export function getMissingBlocks(bitmap: Uint8Array): number[] {
  const missing: number[] = [];
  const totalBlocks = bitmap.length * 8;

  for (let i = 0; i < totalBlocks; i++) {
    if (!isBitmapBitSet(bitmap, i)) {
      missing.push(i);
    }
  }

  return missing;
}

/**
 * Get all block indices with set bits (complete blocks).
 *
 * @param bitmap - Block bitmap
 * @returns Array of block indices that ARE set (complete)
 */
export function getCompleteBlocks(bitmap: Uint8Array): number[] {
  const complete: number[] = [];
  const totalBlocks = bitmap.length * 8;

  for (let i = 0; i < totalBlocks; i++) {
    if (isBitmapBitSet(bitmap, i)) {
      complete.push(i);
    }
  }

  return complete;
}

/**
 * Check if all bits in the bitmap are set (all blocks complete).
 *
 * @param bitmap - Block bitmap
 * @returns true if all bits are set (no missing blocks)
 */
export function isBitmapComplete(bitmap: Uint8Array): boolean {
  for (const byte of bitmap) {
    if (byte !== 0xff) {
      return false;
    }
  }
  return true;
}

/**
 * Compute the bitwise AND of two bitmaps.
 *
 * Useful for computing intersection (e.g., for repair codes).
 *
 * @param a - First bitmap
 * @param b - Second bitmap
 * @returns New bitmap with AND of inputs
 */
export function bitmapAnd(a: Uint8Array, b: Uint8Array): Uint8Array {
  const result = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) {
    result[i] = a[i]! & b[i]!;
  }
  return result;
}

/**
 * Compute the bitwise OR of two bitmaps.
 *
 * Useful for merging block states.
 *
 * @param a - First bitmap
 * @param b - Second bitmap
 * @returns New bitmap with OR of inputs
 */
export function bitmapOr(a: Uint8Array, b: Uint8Array): Uint8Array {
  const result = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) {
    result[i] = a[i]! | b[i]!;
  }
  return result;
}

/**
 * Compute the bitwise XOR of two bitmaps.
 *
 * Useful for detecting differences (e.g., for debugging).
 *
 * @param a - First bitmap
 * @param b - Second bitmap
 * @returns New bitmap with XOR of inputs
 */
export function bitmapXor(a: Uint8Array, b: Uint8Array): Uint8Array {
  const result = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) {
    result[i] = a[i]! ^ b[i]!;
  }
  return result;
}

/**
 * Check if two bitmaps are equal.
 *
 * @param a - First bitmap
 * @param b - Second bitmap
 * @returns true if bitmaps are identical
 */
export function bitmapEquals(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Serialize a bitmap to base64 for storage/transmission.
 *
 * Used for persisting resume tokens (D22).
 *
 * @param bitmap - Block bitmap
 * @returns Base64-encoded string
 */
export function serializeBitmap(bitmap: Uint8Array): string {
  // Convert to binary string then base64
  let binary = '';
  for (const byte of bitmap) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

/**
 * Deserialize a bitmap from base64.
 *
 * @param encoded - Base64-encoded bitmap string
 * @returns Block bitmap
 * @throws {Error} If decoding fails
 */
export function deserializeBitmap(encoded: string): Uint8Array {
  try {
    const binary = atob(encoded);
    const bitmap = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bitmap[i] = binary.charCodeAt(i);
    }
    return bitmap;
  } catch (e) {
    throw new Error(`Failed to deserialize bitmap: ${e}`);
  }
}

/**
 * Convert bitmap to a human-readable string for debugging.
 *
 * Shows a compact representation: 'C' for complete, '.' for incomplete.
 *
 * @param bitmap - Block bitmap
 * @param maxLength - Maximum length (default 64 blocks for readability)
 * @returns String representation
 */
export function bitmapToString(bitmap: Uint8Array, maxLength = 64): string {
  const totalBlocks = Math.min(bitmap.length * 8, maxLength);
  let result = '';
  for (let i = 0; i < totalBlocks; i++) {
    result += isBitmapBitSet(bitmap, i) ? 'C' : '.';
  }
  if (bitmap.length * 8 > maxLength) {
    result += '...';
  }
  return result;
}

/**
 * Calculate bitmap progress as a percentage.
 *
 * @param bitmap - Block bitmap
 * @returns Progress ratio (0.0 to 1.0)
 */
export function getBitmapProgress(bitmap: Uint8Array): number {
  const totalBlocks = bitmap.length * 8;
  if (totalBlocks === 0) return 1.0;
  const complete = countSetBits(bitmap);
  return complete / totalBlocks;
}

/**
 * Validate that a bitmap has the expected size for a given block count.
 *
 * @param bitmap - Block bitmap to validate
 * @param blockCount - Expected block count
 * @returns true if size is correct
 */
export function validateBitmapSize(bitmap: Uint8Array, blockCount: number): boolean {
  const expectedSize = getBitmapSize(blockCount);
  return bitmap.length === expectedSize;
}

/**
 * Tests for streamId derivation (plan.md §7.5, D22).
 *
 * Verifies:
 * - Deterministic streamId generation from file metadata and samples
 * - Same file produces same streamId (resume requirement)
 * - Different files produce different streamIds
 * - Small file handling
 * - Sample extraction logic
 */

import {describe, it, expect, beforeEach} from 'vitest';
import {
  computeStreamId,
  computeStreamIdFromBytes,
  computeStreamIdFromSamples,
  validateStreamId,
  STREAM_ID_SAMPLE_SIZE,
} from '../src/core/hash/stream-id.js';

// Mock File object for browser-like testing
class MockFile {
  constructor(
    public data: Uint8Array,
    public name: string,
    public lastModified: number = Date.now()
  ) {}

  get size(): number {
    return this.data.length;
  }

  slice(start: number, end: number): Blob {
    return new Blob([this.data.slice(start, end)]);
  }
}

describe('stream-id', () => {
  describe('computeStreamIdFromSamples', () => {
    it('should compute deterministic streamId from samples', () => {
      const originalSize = 1000;
      const lastModified = 1234567890;
      const firstSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      const middleSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(2);
      const lastSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(3);

      const streamId1 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        firstSample,
        middleSample,
        lastSample
      );
      const streamId2 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        firstSample,
        middleSample,
        lastSample
      );

      expect(streamId1).toBe(streamId2);
      expect(streamId1).toBeGreaterThan(0);
    });

    it('should detect changes in originalSize', () => {
      const lastModified = 1234567890;
      const samples = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);

      const streamId1 = computeStreamIdFromSamples(
        1000,
        lastModified,
        samples,
        samples,
        samples
      );
      const streamId2 = computeStreamIdFromSamples(
        2000, // Different size
        lastModified,
        samples,
        samples,
        samples
      );

      expect(streamId1).not.toBe(streamId2);
    });

    it('should detect changes in lastModified', () => {
      const originalSize = 1000;
      const samples = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);

      const streamId1 = computeStreamIdFromSamples(
        originalSize,
        1234567890,
        samples,
        samples,
        samples
      );
      const streamId2 = computeStreamIdFromSamples(
        originalSize,
        1234567891, // Different mtime
        samples,
        samples,
        samples
      );

      expect(streamId1).not.toBe(streamId2);
    });

    it('should detect changes in firstSample', () => {
      const originalSize = 1000;
      const lastModified = 1234567890;
      const baseSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      const modifiedSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      modifiedSample[0] = 2; // Flip one bit

      const streamId1 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        baseSample,
        baseSample,
        baseSample
      );
      const streamId2 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        modifiedSample, // Changed
        baseSample,
        baseSample
      );

      expect(streamId1).not.toBe(streamId2);
    });

    it('should detect changes in middleSample', () => {
      const originalSize = 1000;
      const lastModified = 1234567890;
      const baseSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      const modifiedSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      modifiedSample[STREAM_ID_SAMPLE_SIZE - 1] = 2; // Flip last bit

      const streamId1 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        baseSample,
        baseSample,
        baseSample
      );
      const streamId2 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        baseSample,
        modifiedSample, // Changed
        baseSample
      );

      expect(streamId1).not.toBe(streamId2);
    });

    it('should detect changes in lastSample', () => {
      const originalSize = 1000;
      const lastModified = 1234567890;
      const baseSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      const modifiedSample = new Uint8Array(STREAM_ID_SAMPLE_SIZE).fill(1);
      modifiedSample[10] = 2; // Flip one bit

      const streamId1 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        baseSample,
        baseSample,
        baseSample
      );
      const streamId2 = computeStreamIdFromSamples(
        originalSize,
        lastModified,
        baseSample,
        baseSample,
        modifiedSample // Changed
      );

      expect(streamId1).not.toBe(streamId2);
    });
  });

  describe('computeStreamIdFromBytes', () => {
    it('should compute deterministic streamId for small files', () => {
      const fileBytes = new Uint8Array([1, 2, 3, 4, 5]);
      const lastModified = 1234567890;

